00+00:00","tax_amount":12.74},{"admin_extension_id":"82d7f1c0-e9bf-477a-8294-ee1faccfbe40","billing_units":2,"created_at":"2026-10-26T00:32:21.456046+00:00","daily_rate":49,"ends_at":"2026-10-27T22:00:00+00:00","extension_request_id":null,"id":"78cd0eaf-6263-4cb2-9a7d-aae20c9f48ea","markup_percentage":0,"rental_amount":100.28,"rental_id":"a941aa67-a993-4f30-9972-2d11f0a906c6","source":"extension","starts_at":"2026-10-25T22:00:00+00:00","tax_amount":6.37},{"admin_extension_id":"bbcdf421-f991-401e-bb28-de7a0b87d098","billing_units":3,"created_at":"2026-10-28T03:29:53.614418+00:00","daily_rate":49,"ends_at":"2026-10-30T22:00:00+00:00","extension_request_id":null,"id":"192861eb-9b2b-4040-901e-93672562b50a","markup_percentage":0,"rental_amount":150.4,"rental_id":"a941aa67-a993-4f30-9972-2d11f0a906c6","source":"extension","starts_at":"2026-10-27T22:00:00+00:00","tax_amount":9.55},{"admin_extension_id":"90ff6c8a-5abe-4eb4-87a5-87dcbe2d7ead","billing_units":4,"created_at":"2026-10-30T22:00:24.089234+00:00","daily_rate":49,"ends_at":"2026-11-03T23:00:00+00:00","extension_request_id":null,"id":"776d54b3-bb86-40fc-8310-cbf2df6083bd","markup_percentage":0,"rental_amount":200.53,"rental_id":"a941aa67-a993-4f30-9972-2d11f0a906c6","source":"extension","starts_at":"2026-10-30T22:00:00+00:00","tax_amount":12.73},{"admin_extension_id":"9a69abe0-3b8b-45bc-b45c-b7bbaa46966f","billing_units":4,"created_at":"2026-11-03T21:15:10.029306+00:00","daily_rate":49,"ends_at":"2026-11-07T23:00:00+00:00","extension_request_id":null,"id":"e24367b3-91f8-46b7-9cb0-44beb6738396","markup_percentage":0,"rental_amount":196,"rental_id":"a941aa67-a993-4f30-9972-2d11f0a906c6","source":"extension","starts_at":"2026-11-03T23:00:00+00:00","tax_amount":12.45},{"admin_extension_id":"e31c18f5-ddd3-4a24-945d-28d3d3aa51c8","billing_units":4,"created_at":"2026-11-07T20:18:32.427461+00:00","daily_rate":49,"ends_at":"2026-11-11T23:00:00+00:00","extension_request_id":null,"id":"0f7e5131-2df8-4580-91e5-bfa0f80c432c","markup_percentage":0,"rental_amount":196,"rental_id":"a941aa67-a993-4f30-9972-2d11f0a906c6","source":"extension","starts_at":"2026-11-07T23:00:00+00:00","tax_amount":12.45}]}]$specs$::jsonb) order by value->>'rental_id' loop
  select * into strict r from rentals where id=(spec->>'rental_id')::uuid for update;
  if exists(select 1 from rental_audit_events where rental_id=r.id and event_type='manual_discount_basis_reconciled'
    and event_payload->>'repair_key'='20261107-preledger-v1') then continue; end if;
  periods:=rentmect_pricing_snapshot(r.id);
  if r.manual_discount_amount is distinct from (spec->>'discount')::numeric or periods is distinct from spec->'expected_periods' then
   raise exception 'Rental changed since reconciliation review: %',r.id; end if;
  select jsonb_build_object('rental',to_jsonb(r),'periods',periods,
   'payments',(select jsonb_agg(x order by x.id) from rental_payments x where x.rental_id=r.id),
   'charges',(select jsonb_agg(x order by x.id) from rental_charge_items x where x.rental_id=r.id),
   'refunds',(select jsonb_agg(x order by x.id) from rental_payment_refunds x where x.rental_id=r.id),
   'external',(select jsonb_agg(x order by x.id) from rental_external_payment_actions x where x.rental_id=r.id),
   'deposits',(select jsonb_agg(x order by x.id) from rental_deposit_allocations x where x.holder_rental_id=r.id or x.source_rental_id=r.id)) into financial_before;
  select * into strict first_a from rental_amendments where id=(spec->>'first_amendment')::uuid and rental_id=r.id;
  discounted:=first_a.old_values->'pricing_periods';
  previous:=(first_a.old_values->>'manual_discount_amount')::numeric;
  if previous<=0 or (select count(*) from jsonb_array_elements(discounted) where value->>'source'='booking_snapshot')<>1
    or exists(select 1 from jsonb_array_elements(discounted) where value->>'source' not in ('booking_snapshot','extension')) then
    raise exception 'Ambiguous legacy anchor for %',r.id; end if;
  select value into strict b from jsonb_array_elements(discounted) where value->>'source'='booking_snapshot';
  if (b->>'rental_amount')::numeric+previous <> round((b->>'daily_rate')::numeric*(b->>'billing_units')::numeric*(1+(b->>'markup_percentage')::numeric/100),2) then
   raise exception 'Legacy booking residual does not reconcile with saved quoted terms: %',r.id; end if;
  select jsonb_agg(case when value->>'source'='booking_snapshot' then value||jsonb_build_object(
    'rental_amount',(value->>'rental_amount')::numeric+previous,
    'tax_amount',(value->>'tax_amount')::numeric+(first_a.old_values->>'manual_discount_tax_savings')::numeric)
    else value end order by (value->>'starts_at')::timestamptz) into basis from jsonb_array_elements(discounted);
  for a in select * from rental_amendments where rental_id=r.id and (created_at,id)>=(first_a.created_at,first_a.id)
    and old_values ? 'manual_discount_amount' and new_values ? 'manual_discount_amount'
    and jsonb_typeof(old_values->'pricing_periods')='array' and jsonb_typeof(new_values->'pricing_periods')='array'
    order by created_at,id loop
   if previous is distinct from (a.old_values->>'manual_discount_amount')::numeric then raise exception 'Broken amendment chain: %',a.id; end if;
   if (select sum((value->>'rental_amount')::numeric) from jsonb_array_elements(a.old_values->'pricing_periods')) is distinct from (a.old_values->>'rental_total')::numeric
    or (select sum((value->>'tax_amount')::numeric) from jsonb_array_elements(a.old_values->'pricing_periods')) is distinct from (a.old_values->>'tax_amount')::numeric
    or (select sum((value->>'rental_amount')::numeric) from jsonb_array_elements(a.new_values->'pricing_periods')) is distinct from (a.new_values->>'rental_total')::numeric
    or (select sum((value->>'tax_amount')::numeric) from jsonb_array_elements(a.new_values->'pricing_periods')) is distinct from (a.new_values->>'tax_amount')::numeric then
    raise exception 'Amendment snapshot totals differ: %',a.id; end if;
   basis:=rentmect_project_discount_basis(a.old_values->'pricing_periods',basis,discounted);
   -- This reviewed amendment also corrected an extension from $69 to $49/day.
   -- Its $100 rent/$6.35 tax rate reduction is not a manual discount.
   if a.id='52fa19fc-114c-4cf3-8110-7e78e32a128a'::uuid then
    if a.new_values->>'source'<>'administrator_instruction_relayed_by_user'
      or (a.new_values->>'extension_rate_correction')::numeric<>106.35
      or (a.new_values->>'agreed_daily_rate')::numeric<>49 then raise exception 'Reviewed rate correction changed'; end if;
    if not exists(select 1 from jsonb_array_elements(basis) where value->>'admin_extension_id'='e21ef052-0511-4fdb-9192-b95158f4e6b2'
      and (value->>'rental_amount')::numeric=345 and (value->>'tax_amount')::numeric=21.91) then
      raise exception 'Reviewed extension quote changed'; end if;
    select jsonb_agg(case when value->>'admin_extension_id'='e21ef052-0511-4fdb-9192-b95158f4e6b2'
      then value||jsonb_build_object('rental_amount',245,'tax_amount',15.56,'daily_rate',49)
      else value end order by (value->>'starts_at')::timestamptz) into basis from jsonb_array_elements(basis);
   end if;
   discounted:=a.new_values->'pricing_periods'; previous:=(a.new_values->>'manual_discount_amount')::numeric;latest:=a.id;
  end loop;
  if latest is distinct from (spec->>'latest_amendment')::uuid or previous is distinct from r.manual_discount_amount then
   raise exception 'Discount changed after the reviewed chain: %',r.id; end if;
  begin restored:=rentmect_project_discount_basis(periods,basis,discounted); exception when others then raise exception 'Final allocation projection for %: %',r.id,sqlerrm; end;
  select sum((value->>'rental_amount')::numeric)-r.rental_total into delta from jsonb_array_elements(restored);
  if delta is distinct from r.manual_discount_amount then raise exception 'Reconstructed rental discount differs: %, expected %, reconstructed %',r.id,r.manual_discount_amount,delta; end if;
  insert into rental_audit_events(rental_id,user_id,event_type,event_payload) values(r.id,r.user_id,'manual_discount_basis_reconciled',
   jsonb_build_object('repair_key','20261107-preledger-v1','discount_amendment_id',latest,'discount_amount',r.manual_discount_amount,
    'discount_period_basis',restored,'discounted_periods',periods,'anchor_amendment_id',first_a.id,
    'reason','Verified legacy initializer booking residual against saved quote terms, replayed all recorded discount snapshots, and preserved every current invoice, period, receipt and deposit. No money change.'));
  perform rentmect_manual_discount_period_basis(r.id,r.manual_discount_amount,r.manual_discount_tax_savings);
  select jsonb_build_object('rental',(select to_jsonb(x) from rentals x where id=r.id),'periods',rentmect_pricing_snapshot(r.id),
   'payments',(select jsonb_agg(x order by x.id) from rental_payments x where x.rental_id=r.id),
   'charges',(select jsonb_agg(x order by x.id) from rental_charge_items x where x.rental_id=r.id),
   'refunds',(select jsonb_agg(x order by x.id) from rental_payment_refunds x where x.rental_id=r.id),
   'external',(select jsonb_agg(x order by x.id) from rental_external_payment_actions x where x.rental_id=r.id),
   'deposits',(select jsonb_agg(x order by x.id) from rental_deposit_allocations x where x.holder_rental_id=r.id or x.source_rental_id=r.id)) into financial_after;
  if financial_before is distinct from financial_after then raise exception 'Financial preservation assertion failed: %',r.id; end if;
  results:=results||jsonb_build_array(jsonb_build_object('rental_id',r.id,'reconciled',true,'financial_records_unchanged',true));
 end loop;
 perform set_config('rentmect.reconciliation_results',results::text,true);
end $$;
select current_setting('rentmect.reconciliation_results')::jsonb results;
commit;
